                result.Log("client=" + c.VehicleId + " connected=" + c.Connected + " status=" + c.Status);
            foreach (var s in Object.FindObjectsByType<InhaExpress.Client.MapClient.DesktopServerLauncher>(FindObjectsSortMode.None))
